#include <stdio.h>


int main(void)
{
    const char *s = "aaaa";
    int count = 0;
    for (int i = 0; i + 2 <= 4; i++) {
        count += s[i] == 'a' && s[i + 1] == 'a';
    }
    printf("%d\n", count);
    return 0;
}
